/bin/bash -lc "cat > sales.py <<'PY'
\"\"\"Enterprise decisions from public negotiations, contribution margins and research.\"\"\"
import novamind_api as nm,json,re,math
WTP={'E1':41.38,'E2':107.84,'E3':101.62,'D_E01':112.02,'D_E02':62.24,'D_E03':161.82,'D_E04':136.91,'D_E05':99.58,'D_E06':68.46,'D_E07':149.38,'D_E08':124.48,'D_E09':80.90,'D_E10':66.57}
USAGE={'E1':57,'E2':177.7,'E3':114.4,'D_E01':96.6,'D_E02':84.5,'D_E03':144.9,'D_E04':120.7,'D_E05':108.7,'D_E06':60.4,'D_E07':156.9,'D_E08':108.7,'D_E09':72.4,'D_E10':81}
QUOTAS={'A':120,'B':350,'C':450}
COST={'A':.002,'B':.002,'C':.006}
def cost(g,p):return min(USAGE[g],QUOTAS[p])*COST[p]*30

def send(deals,label):
    print(label,len(deals),flush=True)
    for i in range(0,len(deals),400):
        res=nm.enterprise.send_enterprise_deal(deals[i:i+400])
        result=res.get('results',[])
        failures=[r for r in result if not r.get('success')]
        print('SALES_RESULT',label,i,'accepted_submissions',sum(r.get('success',False) for r in result),'failures',json.dumps(failures[:10]),flush=True)
    return len(deals)

def respond():
    rows=nm.query(\"SELECT t.*,c.group_id,s.status AS sub_status,s.effective_price,s.plan AS current_plan FROM enterprise_turns t JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id) JOIN (SELECT customer_id,MAX(message_id) mid FROM enterprise_turns GROUP BY customer_id) x ON t.message_id=x.mid WHERE t.closed=0 AND t.sender"'!='"'agent' AND s.status IN ('lead','subscribed')\")['rows']
    deals=[]
    for r in rows:
        if r['sender']=='system' and r['turn_number']>0: continue
        g=r['group_id'];w=WTP[g];prices={'A':w*.48,'B':w*.56,'C':w*.83}
        if r['sender']=='customer':
            cp=json.loads(r['offer_json'] or '{}').get('price')
            plan=re.search(r'Plan ([ABC])',r['message_text'] or '')
            if cp is not None and cp>0:
                p=plan.group(1) if plan else 'C'
                ratios={'A':[1,1.12,1.4],'B':[.90,1,1.3],'C':[.75,.85,1]}[p]
                prices=dict(zip('ABC',[cp*x for x in ratios]))
        seller=r['thread_type']=='renegotiation' and r['sub_status']=='subscribed'
        offers=[]
        for p in ('AB' if seller else 'ABC'):
            floor=max(3,cost(g,p)*1.35)
            if seller:
                oldmargin=r['effective_price']-cost(g,r['current_plan'])
                floor=max(floor,cost(g,p)+oldmargin+max(2,oldmargin*.08))
            offers.append([p,round(max(prices[p],floor),2)])
        deals.append([r['customer_id'],offers])
    return send(deals,'RESPONDING')

def migrate(limit=200):
    # Only closed latest conversations; never replace an offer awaiting a reply.
    rows=nm.query(f\"SELECT c.customer_id,c.group_id,s.effective_price,s.plan,s.seat_count FROM customers c JOIN subscriptions s USING(customer_id) JOIN (SELECT customer_id,MAX(message_id) mid FROM enterprise_turns GROUP BY customer_id) x USING(customer_id) JOIN enterprise_turns t ON t.message_id=x.mid WHERE c.customer_type='large' AND s.status='subscribed' AND s.plan='C' AND t.closed=1 AND NOT EXISTS(SELECT 1 FROM enterprise_turns past WHERE past.customer_id=c.customer_id AND past.thread_type='renegotiation' AND past.day>=105) ORDER BY s.seat_count DESC LIMIT {limit}\")['rows']
    deals=[]
    for r in rows:
        g=r['group_id']; oldmargin=r['effective_price']-cost(g,'C')
        offers=[]
        for p in 'AB':
            price=max(WTP[g]*(.48 if p=='A' else .56),cost(g,p)*1.35,cost(g,p)+oldmargin+max(2,oldmargin*.08))
            offers.append([p,round(price,2)])
        deals.append([r['customer_id'],offers])
    return send(deals,'MIGRATION')
if __name__=='__main__':respond()
