{
  "/workspace/run-ceobench/forecast_review.py": {
    "type": "add",
    "content": """"Evaluate matured cash forecasts using documented public ledger data."""
import novamind_api as nm,json
from pathlib import Path
d=nm.vars.current_day
cash={};running=0
for r in nm.query('SELECT day,SUM(amount) amount FROM ledger GROUP BY day ORDER BY day')['rows']:
    running+=r['amount'];cash[r['day']]=running
pred=nm.query(f'SELECT * FROM predictions WHERE submit_day+horizon_days<={d} ORDER BY submit_day')['rows']
results=[]
for p in pred:
    actual=cash.get(p['submit_day']+p['horizon_days'])
    if actual is None or actual<=0:continue
    results.append(dict(submit_day=p['submit_day'],horizon=p['horizon_days'],actual=actual,point=p['predicted_value'],relative_error=p['predicted_value']/actual-1,covered=p['predicted_lower']<=actual<=p['predicted_upper']))
summary={}
for h in sorted({r['horizon'] for r in results}):
    rs=[r for r in results if r['horizon']==h and r['submit_day']>=105]
    if not rs:continue
    summary[h]=dict(n=len(rs),mean_error=sum(r['relative_error'] for r in rs)/len(rs),mean_absolute_error=sum(abs(r['relative_error']) for r in rs)/len(rs),coverage=sum(r['covered'] for r in rs)/len(rs))
print('FORECAST_CALIBRATION',json.dumps(dict(day=d,since_day105=summary,recent=results[-8:])),flush=True)
Path(f'strategy_observations/forecast_review_{d:03d}.json').write_text(json.dumps(dict(day=d,results=results,summary=summary),indent=2))
"
  }
}

