    cid=str(row['customer_id'])
    assert cid not in observations, 'Multiple subscription rows require a public-data review.'
    observations[cid]=row
assert set(observations)==set(baseline), 'Missing or additional assigned customers.'
cells={};pooled={}
for cid,base in baseline.items():
    row=observations[cid];active=int(row['status']=='subscribed')
    revenue=active*row['effective_price']*row['seat_count']
    contribution=revenue-active*row['daily_units']*costs[row['plan']]*30
    key=(base['group_id'],base['plan'],base['arm'])
    cells.setdefault(key,[]).append({'survival':active,'revenue':revenue,'contribution':contribution})
    pooled[(base['group_id'],base['plan'])]=pooled.get((base['group_id'],base['plan']),0)+1
results={}
for group in trial['groups']:
    plans={p:n for (g,p),n in pooled.items() if g==group}
    weights={p:n/sum(plans.values()) for p,n in plans.items()}
    arms={}
    for arm in ['control','raise','lower']:
        metrics={}
        for metric in ['survival','revenue','contribution']:
            mean=variance=0
            for plan,weight in weights.items():
                values=[x[metric] for x in cells[(group,plan,arm)]]
                assert len(values)>1, 'Too few customers in a plan stratum.'
                mean+=weight*statistics.mean(values)
                variance+=weight*weight*statistics.variance(values)/len(values)
            metrics[metric]={'mean':mean,'mean_variance':variance}
        arms[arm]=metrics
    contrasts={}
    for arm in ['raise','lower']:
        delta={}
        for metric in ['survival','revenue','contribution']:
            treatment=arms[arm][metric];control=arms['control'][metric]
