q="SELECT t.thread_type,t.closed,t.sender,COUNT(*) companies,SUM(s.seat_count) seats,SUM(s.effective_price*s.seat_count) mrr FROM subscriptions s JOIN customers c USING(customer_id) JOIN (SELECT customer_id,MAX(message_id) mid FROM enterprise_turns GROUP BY customer_id) x USING(customer_id) JOIN enterprise_turns t ON t.message_id=x.mid WHERE c.customer_type='large' AND s.status='subscribed' GROUP BY t.thread_type,t.closed,t.sender"
