"""Offline development allocation scenarios, not game actions or cash forecasts."""
import json, math, sys
from pathlib import Path
day=int(sys.argv[1]) if len(sys.argv)>1 else 203
baseline_day=int(sys.argv[2]) if len(sys.argv)>2 else day
root=Path('strategy_observations')
window=root/f'contribution_window_{day:03d}.json'
economics=json.loads((window if window.exists() else root/f'economics_{day:03d}.json').read_text())['groups']
study_day=max(int(p.stem.split('_')[-1]) for p in root.glob('insights_*.json') if int(p.stem.split('_')[-1])<=day)
study=json.loads((root/f'insights_{study_day:03d}.json').read_text())
policy=json.loads(Path('development_policy.json').read_text())
groups=sorted(economics)
current={g:(10000 if g.startswith(('S','D_S')) else 5000) for g in groups}
current.update({'E1':15000,'E2':20000,'E3':15000})
if policy['from_day']<=baseline_day<policy['until_day']:current.update(policy['targeted'])
for boost in policy.get('temporary',[]):
    if boost['from_day']<=baseline_day<boost['until_day']:current.update(boost['targeted'])
global_current=40000 if baseline_day<420 else 20000
for override in policy.get('shared_temporary',[]):
    if override['from_day']<=baseline_day<override['until_day']:global_current=override['daily_spend']
current_budget=global_current+sum(current.values())
budget=int(sys.argv[3]) if len(sys.argv)>3 else current_budget
floors={g:5000 for g in groups}
floors.update({'D_S05':0,'S1':25000,'S2':20000,'S3':20000,'D_S02':15000,'D_S04':20000,'D_S06':20000,'D_S07':15000,'D_S08':25000,'E1':15000,'E2':35000,'E3':15000,'D_E06':10000,'D_E07':25000,'D_E10':10000})
caps={'D_S05':0}
profits={g:max(0,economics[g].get('projected_monthly_contribution',economics[g].get('contribution',0))) for g in groups}
assert budget>=40000+sum(floors.values()), 'Budget cannot support protected minimums.'
def quality(global_spend,targeted):
    return {g:.9*(.0045*math.log1p(global_spend/5000)+.0225*math.log1p(targeted[g]/5000)) for g in groups}
current_quality=quality(global_current,current)
scenarios=[]
for influence_fraction in [0,.25,.5]:
    weights={g:profits[g]+influence_fraction*sum(weight*profits.get(neighbor,0) for neighbor,weight in study[g].get('reputation_influence',{}).get('outgoing',{}).items()) for g in groups}
    shared_weight=sum(weights.values())
    def allocate(multiplier):
        shared=max(40000,shared_weight*.0045/multiplier-5000)
        targeted={g:max(floors[g],weights[g]*.0225/multiplier-5000) for g in groups}
        for g,cap in caps.items():targeted[g]=min(targeted[g],cap)
        return shared,targeted
    low=1e-12;high=1e6
    for _ in range(100):
        middle=(low+high)/2
        shared,targeted=allocate(middle)
        if shared+sum(targeted.values())>budget:low=middle
        else:high=middle
    shared,targeted=allocate(high)
    targeted={g:round(v/1000)*1000 for g,v in targeted.items()}
    shared=budget-sum(targeted.values())
    candidate_quality=quality(shared,targeted)
    current_score=sum(weights[g]*current_quality[g] for g in groups)
    candidate_score=sum(weights[g]*candidate_quality[g] for g in groups)
    scenarios.append({'neighbor_influence_fraction':influence_fraction,'shared_development':shared,'targeted_development':targeted,
        'candidate_daily_total':shared+sum(targeted.values()),'daily_cost_change':budget-current_budget,'weighted_quality_rate_change_fraction':candidate_score/current_score-1,
        'delivered_quality_difference_after_30_days_from_development_only':{g:30*(candidate_quality[g]-current_quality[g]) for g in groups}})
result={'day':day,'baseline_policy_day':baseline_day,'study_observation_day':study_day,'uses_recent_usage_projection':window.exists(),'current_shared':global_current,'current_targeted':current,'current_total':current_budget,'candidate_budget':budget,'minimum_targets':floors,'scenarios':scenarios,
