for d in [245,252,259,273,279,280]:
 t={g:(10000 if g.startswith(('S','D_S')) else 5000) for g in p['temporary'][-1]['targeted']};t.update({'E1':15000,'E2':20000,'E3':15000})
 if p['from_day']<=d<p['until_day']:t.update(p['targeted'])
 for b in p['temporary']:
  if b['from_day']<=d<b['until_day']:t.update(b['targeted'])
 total=sum(t.values())+shared_development_for_day(d,p)
 if d<280:assert total==530000
 print(d,total)
PY"

