"""Enterprise offers based only on public studies, conversations and realized usage."""
import novamind_api as nm,json,re,math
from pathlib import Path
study=json.loads(sorted(Path('strategy_observations').glob('insights_*.json'))[-1].read_text())
WTP={g:v['estimates']['willingness_to_pay'] for g,v in study.items() if g.startswith(('E','D_E'))}
USAGE={g:study[g]['estimates']['usage_volume'] for g in WTP}
QUOTAS={'A':100,'B':250,'C':400}
COST={'A':.002,'B':.002,'C':.006}
def cost(g,p,usage=None):return min(USAGE[g] if usage is None else usage,QUOTAS[p])*COST[p]*30

def observed_usage(records):
    """Recent per-seat consumption for existing contracts; new leads use study means."""
    subscribed=[r for r in records if r.get('sub_status','subscribed')=='subscribed']
    seats={r['customer_id']:r.get('current_seats',r.get('seat_count',1)) for r in subscribed}
    ids=list(seats);out={};d=nm.vars.current_day
    for i in range(0,len(ids),500):
        selection=','.join(str(int(x)) for x in ids[i:i+500])
        q=f'SELECT customer_id,AVG(usage_units) avg_total FROM daily_usage WHERE day>{d-7} AND customer_id IN ({selection}) GROUP BY customer_id'
        for r in nm.query(q)['rows']:
            if seats[r['customer_id']]>0:out[r['customer_id']]=r['avg_total']/seats[r['customer_id']]
    return out

def send(deals,label):
    print(label,len(deals),flush=True)
    for i in range(0,len(deals),400):
        res=nm.enterprise.send_enterprise_deal(deals[i:i+400])
        result=res.get('results',[])
        failures=[r for r in result if not r.get('success')]
        print('SALES_RESULT',label,i,'accepted_submissions',sum(r.get('success',False) for r in result),'failures',json.dumps(failures[:10]),flush=True)
    return len(deals)

def respond():
    migration_file=Path('strategy_observations/cost_migration_196.json')
    migration=json.loads(migration_file.read_text()) if migration_file.exists() else None
    migration_customers={r['customer_id']:r for r in migration['baseline']} if migration else {}
    rows=[];last=0
    while True:
        page=nm.query(f"SELECT t.*,c.group_id,s.status AS sub_status,s.effective_price,s.plan AS current_plan,s.seat_count AS current_seats,(SELECT MIN(z.day) FROM enterprise_turns z WHERE z.thread_id=t.thread_id) AS thread_start_day FROM enterprise_turns t JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id) JOIN (SELECT customer_id,MAX(message_id) mid FROM enterprise_turns GROUP BY customer_id) x ON t.message_id=x.mid WHERE t.closed=0 AND t.sender!='agent' AND s.status IN ('lead','subscribed') AND c.customer_id>{last} ORDER BY c.customer_id LIMIT 1000")['rows']
        if not page:break
        rows.extend(page);last=page[-1]['customer_id']
    usage=observed_usage(rows);deals=[]
    for r in rows:
        if r['sender']=='system' and r['turn_number']>0:continue
        g=r['group_id'];w=WTP[g];u=usage.get(r['customer_id'])
        requested_plan=None;requested_price=None
        prices=({'A':w*.30,'B':w*.38,'C':w*.68} if g.startswith('D_E') else {'A':w*.48,'B':w*.56,'C':w*.83})
        same_quality=len(set(COST.values()))==1
        if same_quality:
            contribution=max(3,prices['C']-cost(g,'C',u))
            prices={p:cost(g,p,u)+contribution for p in 'ABC'}
        if r['sender']=='customer':
            cp=json.loads(r['offer_json'] or '{}').get('price')
            plan=re.search(r'Plan ([ABC])',r['message_text'] or '')
            if cp is not None and cp>0:
                p=plan.group(1) if plan else 'C'
                requested_plan=plan.group(1) if plan else None
                requested_price=cp
                if same_quality:
                    contribution=max(3,cp-cost(g,p,u))
                    prices={q:cost(g,q,u)+contribution for q in 'ABC'}
                else:
                    ratios={'A':[1,1.12,1.4],'B':[.90,1,1.3],'C':[.75,.85,1]}[p]
                    prices=dict(zip('ABC',[cp*x for x in ratios]))
        if same_quality and r['sub_status']=='subscribed' and r['thread_type'] in ('churn_prevention','renewal'):
            oldmargin=max(0,r['effective_price']-cost(g,r['current_plan'],u))
            fraction=.65 if r['turn_number']>=4 else .85
            prices={p:min(prices[p],cost(g,p,u)+oldmargin*fraction) for p in 'ABC'}
        seller=r['thread_type']=='renegotiation' and r['sub_status']=='subscribed'
        if seller and r['thread_start_day']==196 and r['customer_id'] in migration_customers:
            # This small migration trial offers a customer price concession and
            # lower compute usage at equal quality, with current-cost floors.
            baseline=migration_customers[r['customer_id']]
            oldmargin=max(baseline['current_monthly_contribution']/baseline['current_seats'],r['effective_price']-cost(g,r['current_plan'],u))
            offers=[]
            for alternative in baseline['hypothetical_alternatives']:
                p=alternative['plan'];ceiling=alternative['proposed_price']
                if requested_plan==p and requested_price is not None:
                    ceiling=min(ceiling,requested_price)
                floor=max(3,cost(g,p,u)*1.35,cost(g,p,u)+oldmargin+max(1,oldmargin*.03))
                if ceiling>=floor:
                    offers.append([p,round(ceiling,2)])
            if offers:deals.append([r['customer_id'],offers])
            else:print('MIGRATION_NO_FEASIBLE_CONCESSION',r['customer_id'],flush=True)
            continue
        repricing=seller and r['thread_start_day']>=147
        offers=[];floors={}
        for p in ('AB' if seller and not repricing else 'ABC'):
            floor=max(3,cost(g,p,u)*1.35)
            if seller:
                oldmargin=r['effective_price']-cost(g,r['current_plan'],u)
                floor=max(floor,cost(g,p,u)+oldmargin+max(2,oldmargin*(.10 if repricing else .08)))
            floors[p]=floor
            offers.append([p,round(max(prices[p],floor),2)])
        if seller and requested_plan in floors and requested_price>=floors[requested_plan]:
            # Honor a profitable explicit counteroffer without introducing alternatives
            # or increasing C's price to match a hypothetical B contribution.
            offers=[[requested_plan,round(requested_price,2)]]
        elif repricing:
            # Premium pricing covers its extra compute cost relative to B.
            offers[2][1]=round(max(offers[2][1],offers[1][1]+cost(g,'C',u)-cost(g,'B',u)+2),2)
        deals.append([r['customer_id'],offers])
    return send(deals,'RESPONDING')

