"""Fixed retail price experiment, using public observations only."""
import json
from pathlib import Path
import novamind_api as nm
from pricing_trial_registry import combine_active_trials
PATH=Path('pricing_trial.json')
def active_trial():
    paths=[PATH]
    registry=Path('additional_pricing_trials.json')
    if registry.exists():
        additional=[Path(p) for p in json.loads(registry.read_text())]
        assert all(p.exists() for p in additional), 'Registered trial baseline is missing.'
        paths.extend(additional)
    assert len(paths)==len(set(paths)), 'Duplicate trial baseline path.'
    trials=[json.loads(p.read_text()) for p in paths if p.exists()]
    policy=json.loads(Path('retail_policy.json').read_text())
    return combine_active_trials(trials,nm.vars.current_day,policy)

def anticipated_adjustments_original():
    result={'by_group':{},'by_group_plan':{},'by_billing_day':{},'total':0}
    trial=active_trial()
    if not trial:return result
    people=trial['customers'];ids=[int(cid) for cid,r in people.items() if r['delta']]
    for i in range(0,len(ids),1000):
        selection=','.join(map(str,ids[i:i+1000]))
        rs=nm.query(f"SELECT s.customer_id,c.group_id,s.plan,s.seat_count,s.billing_day_mod30 FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND s.listed_price IN (151,171,241) AND s.customer_id IN ({selection})")['rows']
        for r in rs:
            amount=people[str(r['customer_id'])]['delta']*r['seat_count']
            for kind,key in [('by_group',r['group_id']),('by_group_plan',r['group_id']+':'+r['plan']),('by_billing_day',int(r['billing_day_mod30']))]:
                result[kind][key]=result[kind].get(key,0)+amount
            result['total']+=amount
    return result

def anticipated_adjustments_grouped():
    """Read-only aggregation, verified exactly against original on day210."""
    result={'by_group':{},'by_group_plan':{},'by_billing_day':{},'total':0}
    trial=active_trial()
    if not trial:return result
    cohorts={}
    for cid,person in trial['customers'].items():
        if person['delta']:
            cohorts.setdefault((person['group_id'],person['delta']),[]).append(int(cid))
    for (_,delta),ids in cohorts.items():
        for i in range(0,len(ids),5000):
            selection=','.join(map(str,ids[i:i+5000]))
            rs=nm.query(f"SELECT c.group_id,s.plan,s.billing_day_mod30,SUM(s.seat_count) seats FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND s.listed_price IN (151,171,241) AND s.customer_id IN ({selection}) GROUP BY c.group_id,s.plan,s.billing_day_mod30")['rows']
            for r in rs:
                amount=delta*r['seats']
                for kind,key in [('by_group',r['group_id']),('by_group_plan',r['group_id']+':'+r['plan']),('by_billing_day',int(r['billing_day_mod30']))]:
                    result[kind][key]=result[kind].get(key,0)+amount
                result['total']+=amount
    return result

def anticipated_adjustments():
    return anticipated_adjustments_grouped()
"""Offline analysis of saved public trial observations; no simulator calls."""
import json, math, statistics, sys
from pathlib import Path
day=int(sys.argv[1])
trial_path=Path(sys.argv[2]) if len(sys.argv)>2 else Path('pricing_trial.json')
trial=json.loads(trial_path.read_text())
label='' if trial_path.name=='pricing_trial.json' else f"_{trial['from_day']}"
review=json.loads(Path(f'strategy_observations/pricing_trial_review{label}_{day:03d}.json').read_text())
baseline=trial['customers'];costs=review['model_costs']
observations={}
for row in review['observations']:
    cid=str(row['customer_id'])
    assert cid not in observations, 'Multiple subscription rows require a public-data review.'
    observations[cid]=row
assert set(observations)==set(baseline), 'Missing or additional assigned customers.'
cells={};pooled={}
for cid,base in baseline.items():
    row=observations[cid];active=int(row['status']=='subscribed')
    revenue=active*row['effective_price']*row['seat_count']
    contribution=revenue-active*row['daily_units']*costs[row['plan']]*30
    key=(base['group_id'],base['plan'],base['arm'])
    cells.setdefault(key,[]).append({'survival':active,'revenue':revenue,'contribution':contribution})
    pooled[(base['group_id'],base['plan'])]=pooled.get((base['group_id'],base['plan']),0)+1
results={}
for group in trial['groups']:
    plans={p:n for (g,p),n in pooled.items() if g==group}
    weights={p:n/sum(plans.values()) for p,n in plans.items()}
    arms={}
    for arm in ['control','raise','lower']:
        metrics={}
        for metric in ['survival','revenue','contribution']:
            mean=variance=0
            for plan,weight in weights.items():
                values=[x[metric] for x in cells[(group,plan,arm)]]
                assert len(values)>1, 'Too few customers in a plan stratum.'
                mean+=weight*statistics.mean(values)
                variance+=weight*weight*statistics.variance(values)/len(values)
            metrics[metric]={'mean':mean,'mean_variance':variance}
        arms[arm]=metrics
    contrasts={}
    for arm in ['raise','lower']:
        delta={}
        for metric in ['survival','revenue','contribution']:
            treatment=arms[arm][metric];control=arms['control'][metric]
            difference=treatment['mean']-control['mean']
            se=math.sqrt(treatment['mean_variance']+control['mean_variance'])
            delta[metric]={'difference':difference,'ci95':[difference-1.96*se,difference+1.96*se],
                'ci_familywise_8_comparisons_95':[difference-2.735*se,difference+2.735*se]}
        contrasts[arm]=delta
    results[group]={'baseline_plan_weights':weights,'adjusted_means':arms,'versus_control':contrasts}
output={'day':day,'first_renewals_mature':review['all_first_renewals_mature'],'groups':results,
    'interpretation':'Intention-to-treat endpoint values per original customer, standardized to pooled baseline plan mix. Cancelled customers contribute zero. Normal-approximation uncertainty; familywise intervals cover eight treatment-control contrasts for each metric. Endpoint monthly contribution is not cumulative experiment cash. No price policy changes are made.'}
Path(f'strategy_observations/pricing_trial_analysis{label}_{day:03d}.json').write_text(json.dumps(output,indent=2))
print(json.dumps(output,indent=2))
"""Pure price-basis arithmetic; no simulator calls or file writes."""

LIST_PRICES={'A':151,'B':171,'C':241}

def preserve_assigned_prices(trial,policy):
    """Express immutable experimental prices relative to the current base price."""
    assert policy['prices']==LIST_PRICES, 'Review active trials before changing list prices.'
    people={}
    for cid,person in trial['customers'].items():
        assert person['listed_price']==LIST_PRICES[person['plan']]
        original_offset=LIST_PRICES[person['plan']]-LIST_PRICES['A']
        original_base=person['baseline_recurring_price']-original_offset
        relative_delta=original_base+person['delta']-policy['target_A'][person['group_id']]
        people[cid]=dict(person,delta=relative_delta)
    return dict(trial,customers=people)

