import novamind_api as nm,json
from pathlib import Path
from pricing_trial import active_trial
POLICY=Path('/workspace/run-ceobench/retail_policy.json')
def maintain():
    if not POLICY.exists():return 0
    policy=json.loads(POLICY.read_text()); discounts={}; last=0
    trial=active_trial()
    experimental=trial['customers'] if trial else {}
    prices=','.join(str(x) for x in policy['prices'].values())
    while True:
        rows=nm.query(f"SELECT s.customer_id,c.group_id FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND c.customer_type='small' AND s.listed_price IN ({prices}) AND s.customer_id>{last} ORDER BY s.customer_id LIMIT 5000")['rows']
        if not rows:break
        for r in rows:
            g=r['group_id'];cid=str(r['customer_id'])
            discount=policy['prices']['A']-policy['target_A'][g]-policy['legacy_group_promotions'].get(g,0)-experimental.get(cid,{}).get('delta',0)
            assert discount>=0, 'Experiment cannot exceed available coupon.'
            discounts[cid]=discount
        last=rows[-1]['customer_id']
    result=nm.pricing.set_promotion(by_customer=discounts)
    print('RETAIL_ONGOING_COUPONS',len(discounts),flush=True)
    return len(discounts)
if __name__=='__main__':maintain()
"""Pure price-basis arithmetic; no simulator calls or file writes."""

LIST_PRICES={'A':151,'B':171,'C':241}

def preserve_assigned_prices(trial,policy):
    """Express immutable experimental prices relative to the current base price."""
    assert policy['prices']==LIST_PRICES, 'Review active trials before changing list prices.'
    people={}
    for cid,person in trial['customers'].items():
        assert person['listed_price']==LIST_PRICES[person['plan']]
        original_offset=LIST_PRICES[person['plan']]-LIST_PRICES['A']
        original_base=person['baseline_recurring_price']-original_offset
        relative_delta=original_base+person['delta']-policy['target_A'][person['group_id']]
        people[cid]=dict(person,delta=relative_delta)
    return dict(trial,customers=people)
