"""Read-only watcher of a documented CLI request. Never submits or resumes."""
import json,subprocess,sys,time
from pathlib import Path
request=sys.argv[1]
while True:
 p=subprocess.run(['./novamind-operation','request-status',request],capture_output=True,text=True)
 if p.returncode:
  print('STATUS_READ_FAILED',p.returncode,p.stdout,p.stderr,flush=True);break
 try:r=json.loads(p.stdout)
 except Exception:
  print('UNPARSED_STATUS',p.stdout[:3000],p.stderr[:1000],flush=True);break
 print(time.strftime('%H:%M:%S',time.gmtime()),request,r.get('status'),flush=True)
 if r.get('status')!='pending':
  Path('strategy_observations',f'request_{request}.json').write_text(json.dumps(r,indent=2))
  print('TERMINAL_STATUS',r.get('status'),'saved public result',flush=True);break
