import json,math,sys
from pathlib import Path

day=int(sys.argv[1]); root=Path('strategy_observations')
snapshots=[]
for p in root.glob('adaptive_*.json'):
    d=int(p.stem.split('_')[-1])
    if d<=day:
        x=json.loads(p.read_text())
        if 'research' in x:
            snapshots.append((d,x['research']))
snapshots.sort()
assert snapshots and snapshots[-1][0]==day, 'Requires the current saved public research snapshot.'
first_day=snapshots[0][0]
current={r['project_id']:r for r in snapshots[-1][1]}
observed={pid:[] for pid in current}
for d,projects in snapshots:
    for p in projects:
        if p['project_id'] in observed:
            observed[p['project_id']].append((d,p['status']))
records=[]
for pid,p in current.items():
    start=p['started_day']; mean=p['expected_completion_day']-start
    if start<first_day or mean<=0:
        continue
    complete=[d for d,status in observed[pid] if status=='completed']
    in_progress=[d for d,status in observed[pid] if status=='in_progress']
    if complete:
        upper=min(complete)-start
        lower=max([d-start for d in in_progress if d<min(complete)]+[0])
    else:
        lower=day-start; upper=None
    records.append(dict(project_id=pid,tier=p['tier'],expected_duration=mean,
                        lower_exclusive_days=lower,upper_inclusive_days=upper,
                        boost_ratio=(p['quality_boost_applied']/p['expected_quality_boost']) if complete else None))

def cdf(t,mu,sigma):
    return 0 if t<=0 else (1+math.erf((math.log(t)-mu)/(sigma*math.sqrt(2))))/2
def log_likelihood(mean_multiplier,cv):
    sigma=math.sqrt(math.log1p(cv*cv)); mu=math.log(mean_multiplier)-sigma*sigma/2
    total=0
    for r in records:
        low=cdf(r['lower_exclusive_days']/r['expected_duration'],mu,sigma)
        high=1 if r['upper_inclusive_days'] is None else cdf(r['upper_inclusive_days']/r['expected_duration'],mu,sigma)
        total+=math.log(max(1e-300,high-low))
    return total
grid=[dict(mean_multiplier=m/100,cv=c/100,log_likelihood=log_likelihood(m/100,c/100))
      for m in range(60,151,2) for c in range(20,111,2)]
best=max(grid,key=lambda r:r['log_likelihood'])
near=[r for r in grid if r['log_likelihood']>=best['log_likelihood']-3]
ratios=sorted(r['boost_ratio'] for r in records if r['boost_ratio'] is not None)
result={'day':day,'earliest_included_snapshot':first_day,'records':records,
        'completed_count':sum(r['upper_inclusive_days'] is not None for r in records),
        'right_censored_count':sum(r['upper_inclusive_days'] is None for r in records),
        'pooled_relative_lognormal_grid_best':best,
        'near_best_3_loglik_units_sensitivity':{
            'mean_multiplier_range':[min(r['mean_multiplier'] for r in near),max(r['mean_multiplier'] for r in near)],
            'cv_range':[min(r['cv'] for r in near),max(r['cv'] for r in near)]},
        'completed_boost_ratio_mean':sum(ratios)/len(ratios) if ratios else None,
        'note':'Own saved public observations only. Completion occurs after the last observed in-progress day and on or before first completed observation; open projects are right-censored at the current day. Projects started before the first retained snapshot are excluded. Fits a common lognormal distribution of duration divided by the displayed tier mean; pooling, lognormal form and independence are assumptions. Grid ranges are sensitivity bounds, not calibrated confidence intervals. Completion-time rounding is not modeled. No causal quality cash value, optimal cutoff, game action or private-state access.'}
path=root/f'research_duration_review_{day:03d}.json';path.write_text(json.dumps(result,indent=2))
print(json.dumps({k:v for k,v in result.items() if k!='records'},indent=2))
"
  }
