"""Pure helpers for distinct fixed price trials; no simulator calls or writes.

Used by the live coupon policy. The original pricing_trial.json remains an
immutable baseline, even if another trial is added.
"""
from pricing_trial_prices import preserve_assigned_prices


def combine_active_trials(trials, day, policy):
    """Rebase active assignments and reject overlapping customer assignments."""
    active = []
    seen = set()
    for trial in trials:
        if not trial['from_day'] <= day < trial['until_day']:
            continue
        rebased = preserve_assigned_prices(trial, policy)
        overlap = seen.intersection(rebased['customers'])
        if overlap:
            raise ValueError('Overlapping active price trials require review.')
        seen.update(rebased['customers'])
        active.append(rebased)
    if not active:
        return None
    if len(active) == 1:
        return active[0]
    return {
        'from_day': min(trial['from_day'] for trial in active),
        'until_day': max(trial['until_day'] for trial in active),
        'groups': sorted({g for trial in active for g in trial['groups']}),
        'customers': {
            cid: person
            for trial in active
            for cid, person in trial['customers'].items()
        },
        'note': 'Combined view only; each source baseline remains immutable.',
    }
