"""Fixed retail price experiment, using public observations only."""
import json
from pathlib import Path
import novamind_api as nm
from pricing_trial_registry import combine_active_trials
PATH=Path('pricing_trial.json')
def active_trial():
    paths=[PATH]
    registry=Path('additional_pricing_trials.json')
    if registry.exists():
        additional=[Path(p) for p in json.loads(registry.read_text())]
        assert all(p.exists() for p in additional), 'Registered trial baseline is missing.'
        paths.extend(additional)
    assert len(paths)==len(set(paths)), 'Duplicate trial baseline path.'
    trials=[json.loads(p.read_text()) for p in paths if p.exists()]
    policy=json.loads(Path('retail_policy.json').read_text())
    return combine_active_trials(trials,nm.vars.current_day,policy)

def anticipated_adjustments_original():
    result={'by_group':{},'by_group_plan':{},'by_billing_day':{},'total':0}
    trial=active_trial()
    if not trial:return result
    people=trial['customers'];ids=[int(cid) for cid,r in people.items() if r['delta']]
    for i in range(0,len(ids),1000):
        selection=','.join(map(str,ids[i:i+1000]))
        rs=nm.query(f"SELECT s.customer_id,c.group_id,s.plan,s.seat_count,s.billing_day_mod30 FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND s.listed_price IN (151,171,241) AND s.customer_id IN ({selection})")['rows']
        for r in rs:
            amount=people[str(r['customer_id'])]['delta']*r['seat_count']
            for kind,key in [('by_group',r['group_id']),('by_group_plan',r['group_id']+':'+r['plan']),('by_billing_day',int(r['billing_day_mod30']))]:
                result[kind][key]=result[kind].get(key,0)+amount
            result['total']+=amount
    return result

def anticipated_adjustments_grouped():
    """Read-only aggregation, verified exactly against original on day210."""
    result={'by_group':{},'by_group_plan':{},'by_billing_day':{},'total':0}
    trial=active_trial()
    if not trial:return result
    cohorts={}
    for cid,person in trial['customers'].items():
        if person['delta']:
            cohorts.setdefault((person['group_id'],person['delta']),[]).append(int(cid))
    for (_,delta),ids in cohorts.items():
        for i in range(0,len(ids),5000):
            selection=','.join(map(str,ids[i:i+5000]))
            rs=nm.query(f"SELECT c.group_id,s.plan,s.billing_day_mod30,SUM(s.seat_count) seats FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND s.listed_price IN (151,171,241) AND s.customer_id IN ({selection}) GROUP BY c.group_id,s.plan,s.billing_day_mod30")['rows']
            for r in rs:
                amount=delta*r['seats']
                for kind,key in [('by_group',r['group_id']),('by_group_plan',r['group_id']+':'+r['plan']),('by_billing_day',int(r['billing_day_mod30']))]:
                    result[kind][key]=result[kind].get(key,0)+amount
                result['total']+=amount
    return result

def anticipated_adjustments():
    return anticipated_adjustments_grouped()

