{
  "/workspace/run-ceobench/audit_price301.py": {
    "type": "add",
    "content": """"Read-only check of assigned prices after the first week of renewals."""
import json
from pathlib import Path
import novamind_api as nm
assert nm.vars.current_day==308
trial=json.loads(Path('pricing_trial_301.json').read_text())
cohorts={}
for cid,r in trial['customers'].items():
    offset={'A':0,'B':20,'C':90}[r['plan']]
    base=r['baseline_recurring_price']-offset
    cohorts.setdefault((r['group_id'],r['arm'],base+r['delta']),[]).append(int(cid))
results=[]
for (group,arm,price),ids in cohorts.items():
    selection=','.join(map(str,ids))
    row=nm.query(f"SELECT COUNT(*) renewed_active,SUM(CASE WHEN ABS(s.effective_price-(s.listed_price-151+{price}))>.00001 THEN 1 ELSE 0 END) mismatches FROM subscriptions s WHERE s.status='subscribed' AND s.listed_price IN (151,171,241) AND s.billing_day_mod30 IN (2,3,4,5,6,7,8) AND s.customer_id IN ({selection})")['rows'][0]
    results.append({'group':group,'arm':arm,'assigned_A_price':price,**row})
output={'day':308,'rows':results,'note':'Checks active original assignees whose scheduled billing day occurred302-308. Does not infer application for customers not yet renewed. All original randomized assignments remain immutable.'}
Path('strategy_observations/price301_application_audit_308.json').write_text(json.dumps(output,indent=2))
print('PRICE301_APPLICATION_AUDIT',json.dumps(output),flush=True)
assert sum(r['mismatches'] or 0 for r in results)==0, 'Investigate observed assigned-price mismatches before further actions.'
"
  }
}

