"""Read-only recurring contribution using each active customer's recent usage."""
import json
from pathlib import Path
import novamind_api as nm
from pricing_trial import anticipated_adjustments

d=nm.vars.current_day
policy=json.loads(Path('retail_policy.json').read_text())
config=nm.query('SELECT * FROM config_history ORDER BY day DESC LIMIT 1')['rows'][0]
costs={p:{1:.0003,2:.002,3:.006,4:.012,5:.03}[config['tier_'+p]] for p in 'ABC'}
price_case='CASE c.group_id '+' '.join(f"WHEN '{g}' THEN {v}" for g,v in policy['target_A'].items())+' ELSE 151 END'
price=f"CASE WHEN c.customer_type='small' AND s.listed_price IN (151,171,241) THEN s.listed_price-151+({price_case}) ELSE s.effective_price END"
query=f"""SELECT c.group_id,s.plan,COUNT(*) customers,SUM(s.seat_count) seats,
SUM(({price})*s.seat_count) mrr,SUM(COALESCE(u.mean_daily_units,0)) projected_daily_units
FROM subscriptions s JOIN customers c USING(customer_id)
LEFT JOIN (SELECT customer_id,AVG(usage_units) mean_daily_units
FROM daily_usage WHERE day>{d-7} GROUP BY customer_id) u ON u.customer_id=c.customer_id
WHERE s.status='subscribed' GROUP BY c.group_id,s.plan"""
records=nm.query(query)['rows']
adjustments=anticipated_adjustments()
groups={}
for row in records:
    row['mrr']+=adjustments['by_group_plan'].get(row['group_id']+':'+row['plan'],0)
    row['projected_monthly_compute']=row['projected_daily_units']*costs[row['plan']]*30
    row['projected_monthly_contribution']=row['mrr']-row['projected_monthly_compute']
    group=groups.setdefault(row['group_id'],dict(mrr=0,projected_daily_units=0,projected_monthly_compute=0,projected_monthly_contribution=0))
    for key in group:group[key]+=row[key]
totals={key:sum(group[key] for group in groups.values()) for key in next(iter(groups.values()))}
result={'day':d,'totals':totals,'groups':groups,'group_plans':records,
        'note':'Active-book recurring contribution at current model costs, with mean usage per observed customer-day in the last seven days. Recent starts use available days. Plan changes can mix usage before and after the change. This is a projection, not realized cash or a causal treatment effect. Compare with current-day economics and the ledger.'}
Path(f'strategy_observations/contribution_window_{d:03d}.json').write_text(json.dumps(result,indent=2))
print('CONTRIBUTION_WINDOW',json.dumps(dict(result,group_plans='saved in file')),flush=True)

