    ids=[int(cid) for cid in people];summary={};observed=[]
    for r in people.values():
        z=summary.setdefault(r['group_id']+':'+r['arm'],{'baseline_n':0,'active':0,'mrr':0,'monthly_compute':0,'contribution':0,'cancelled':0})
        z['baseline_n']+=1
    for i in range(0,len(ids),1000):
        selection=','.join(map(str,ids[i:i+1000]))
        rs=nm.query(f"SELECT s.customer_id,s.status,s.plan,s.effective_price,s.seat_count,s.end_day,COALESCE(MAX(u.daily_units),0) daily_units FROM subscriptions s LEFT JOIN (SELECT customer_id,AVG(usage_units) daily_units FROM daily_usage WHERE day>{d-7} AND customer_id IN ({selection}) GROUP BY customer_id) u ON u.customer_id=s.customer_id WHERE s.customer_id IN ({selection}) GROUP BY s.customer_id,s.status,s.plan,s.effective_price,s.seat_count,s.end_day")['rows']
        observed.extend(rs)
        for r in rs:
            base=people[str(r['customer_id'])];z=summary[base['group_id']+':'+base['arm']]
            if r['status']=='subscribed':
                z['active']+=1;z['mrr']+=r['effective_price']*r['seat_count'];z['monthly_compute']+=r['daily_units']*costs[r['plan']]*30
            elif r['status']=='cancelled':z['cancelled']+=1
    assert len(observed)==len(people) and {str(r['customer_id']) for r in observed}==set(people), 'Missing or duplicate trial customers.'
