import json,math,re,sys
from pathlib import Path

day=int(sys.argv[1]);root=Path('strategy_observations')
dashboards=[]
for path in sorted(root.glob('advance_*.json')):
    data=json.loads(path.read_text())
    if not data.get('success') or data.get('day',9999)>day:continue
    text=data.get('dashboard','')
    groups={}
    for line in text.splitlines():
        m=re.match(r'^(D_[SE]\d\d|[SE]\d)\s+([\d.]+)\s+([\d.]+)\s+([\d.]+)\s+\+([\d.]+)',line)
        if m:groups[m[1]]={'nominal_quality_by_plan':dict(zip('ABC',map(float,m.group(2,3,4)))),
                          'accumulated_group_bonus':float(m[5])}
    if groups:
        model_match=re.search(r'Model Tiers: A=(\d), B=(\d), C=(\d)',text)
        assert model_match, 'Saved public dashboard must identify model tiers.'
        models=dict(zip('ABC',map(int,model_match.groups())))
        dashboards.append((data['day'],groups,models))
dashboards.sort(key=lambda x:x[0]);assert dashboards[-1][0]==day
study_history={}
for path in sorted(root.glob('insights_*.json')):
    observed=int(path.stem.rsplit('_',1)[1])
    if observed>day:continue
    for group,data in json.loads(path.read_text()).items():
        if data.get('info_level')!=5:continue
        history=study_history.setdefault(group,[])
        estimates=data['estimates']
        if not history or history[-1]['estimates']!=estimates:
            history.append({'first_observed_day':observed,'estimates':estimates})
policy=json.loads(Path('development_policy.json').read_text())
# This is a review of allocated development, not an implementation of policy.
allocation={}
if policy['from_day']<=day<policy['until_day']:allocation.update(policy['targeted'])
for period in policy.get('temporary',[]):
    if period['from_day']<=day<period['until_day']:allocation.update(period['targeted'])
result={}
current_models=dashboards[-1][2]
multipliers={1:.60,2:.75,3:.90,4:1.0,5:1.10}
for group,data in dashboards[-1][1].items():
    history=study_history.get(group,[])
    if not history:continue
    latest=history[-1];floor=latest['estimates']['quality_floor_q_min']
    nominal=data['nominal_quality_by_plan']['A']
    row={**data,'latest_study_first_observed_day':latest['first_observed_day'],
         'frozen_floor_estimate':floor,'nominal_minus_frozen_floor':nominal-floor,
         'current_models':current_models,
         'nominal_minus_frozen_floor_by_plan':{p:q-floor for p,q in data['nominal_quality_by_plan'].items()},
         'nominal_quality_if_tier2':nominal*.75/multipliers[current_models['A']],
         'recent_frozen_floor_observations':[{'first_observed_day':h['first_observed_day'],
           'floor':h['estimates']['quality_floor_q_min']} for h in history[-3:]]}
    budget=allocation.get(group)
    if budget is not None:
        row['allocated_targeted_daily_spend']=budget
        row['hypothetical_targeted_cut_sensitivity']=[]
        for new_budget in sorted({0,budget/2,max(0,budget-10000)}):
            if new_budget>=budget:continue
            # Mechanic coefficient from simulator-instructions.md, not the
            # inconsistent older coefficient in tools-reference.md.
            per_day=multipliers[current_models['A']]*.0225*math.log((1+budget/5000)/(1+new_budget/5000))
            row['hypothetical_targeted_cut_sensitivity'].append({
                'new_daily_budget':new_budget,'daily_cash_saving':budget-new_budget,
                'nominal_quality_foregone_28days':per_day*28,
                'nominal_quality_foregone_until500':per_day*(500-day)})
    if len(dashboards)>1 and group in dashboards[-2][1]:
        previous_day,previous,_=dashboards[-2]
        row['last_interval_days']=day-previous_day
        row['observed_group_bonus_gain']=data['accumulated_group_bonus']-previous[group]['accumulated_group_bonus']
    result[group]=row
output={'day':day,'groups':result,
        'note':__doc__+' Counterfactual cuts are mechanical sensitivity only; they exclude R&D, future drift, competitor events and feedback. No price or churn model is identified. Tier2 figures are hypothetical, NOT an action recommendation. Study timestamps are first observation dates, not exact measurement dates.'}
(root/f'quality_spend_review_{day:03d}.json').write_text(json.dumps(output,indent=2))
for group,row in result.items():
