"""Offline analysis of saved public trial observations; no simulator calls."""
import json, math, statistics, sys
from pathlib import Path
day=int(sys.argv[1])
trial_path=Path(sys.argv[2]) if len(sys.argv)>2 else Path('pricing_trial.json')
trial=json.loads(trial_path.read_text())
label='' if trial_path.name=='pricing_trial.json' else f"_{trial['from_day']}"
review=json.loads(Path(f'strategy_observations/pricing_trial_review{label}_{day:03d}.json').read_text())
baseline=trial['customers'];costs=review['model_costs']
observations={}
for row in review['observations']:
    cid=str(row['customer_id'])
    assert cid not in observations, 'Multiple subscription rows require a public-data review.'
    observations[cid]=row
assert set(observations)==set(baseline), 'Missing or additional assigned customers.'
cells={};pooled={}
for cid,base in baseline.items():
    row=observations[cid];active=int(row['status']=='subscribed')
    revenue=active*row['effective_price']*row['seat_count']
    contribution=revenue-active*row['daily_units']*costs[row['plan']]*30
    key=(base['group_id'],base['plan'],base['arm'])
    cells.setdefault(key,[]).append({'survival':active,'revenue':revenue,'contribution':contribution})
    pooled[(base['group_id'],base['plan'])]=pooled.get((base['group_id'],base['plan']),0)+1
results={}
for group in trial['groups']:
    plans={p:n for (g,p),n in pooled.items() if g==group}
    weights={p:n/sum(plans.values()) for p,n in plans.items()}
    arms={}
    for arm in ['control','raise','lower']:
        metrics={}
        for metric in ['survival','revenue','contribution']:
            mean=variance=0
            for plan,weight in weights.items():
                values=[x[metric] for x in cells[(group,plan,arm)]]
                assert len(values)>1, 'Too few customers in a plan stratum.'
                mean+=weight*statistics.mean(values)
                variance+=weight*weight*statistics.variance(values)/len(values)
            metrics[metric]={'mean':mean,'mean_variance':variance}
        arms[arm]=metrics
    contrasts={}
    for arm in ['raise','lower']:
        delta={}
        for metric in ['survival','revenue','contribution']:
            treatment=arms[arm][metric];control=arms['control'][metric]
            difference=treatment['mean']-control['mean']
            se=math.sqrt(treatment['mean_variance']+control['mean_variance'])
            delta[metric]={'difference':difference,'ci95':[difference-1.96*se,difference+1.96*se],
                'ci_familywise_8_comparisons_95':[difference-2.735*se,difference+2.735*se]}
        contrasts[arm]=delta
    results[group]={'baseline_plan_weights':weights,'adjusted_means':arms,'versus_control':contrasts}
output={'day':day,'first_renewals_mature':review['all_first_renewals_mature'],'groups':results,
    'interpretation':'Intention-to-treat endpoint values per original customer, standardized to pooled baseline plan mix. Cancelled customers contribute zero. Normal-approximation uncertainty; familywise intervals cover eight treatment-control contrasts for each metric. Endpoint monthly contribution is not cumulative experiment cash. No price policy changes are made.'}
Path(f'strategy_observations/pricing_trial_analysis{label}_{day:03d}.json').write_text(json.dumps(output,indent=2))
print(json.dumps(output,indent=2))

