"""Offline combination of exact early cash and later conservative cost bounds."""
import json,sys,math
from pathlib import Path
ROOT=Path('strategy_observations')
kind=sys.argv[1];end=int(sys.argv[2])
assert (kind,end) in [('ads280',350),('price301',364),('enterprise315',350),('enterprise315',378)]
def read(name):return json.loads((ROOT/name).read_text())
def bounded(start,stop):
    x=read(f'bounded_cash_{kind}_{start}_{stop}.json')
    assert (x['period_start_exclusive'],x['period_end_inclusive'])==(start,stop)
    assert all(v=={'first_day':start+1,'last_day':stop,'days':stop-start} for v in x['temporal_coverage'].values())
    return x
out={'kind':kind,'day':end,'note':'Exact captures through336 plus verified later intervals with historical compute-cost bounds. Point identification is unavailable when customer plan histories are unknown. Normal confidence regions are approximate; unpaired cross-interval standard errors are summed conservatively. All original assignments retained. No game action.'}
if kind=='enterprise315':
    from enterprise_trial_analysis315 import paired
    t=json.loads(Path('enterprise_trial_315.json').read_text())
    old=read('enterprise_trial_cash_315_315_336.json')
    low={str(r['customer_id']):r['adjusted_contribution'] for r in old['customers']};high=low.copy()
    for a,b in [(336,350)]+([(350,378)] if end==378 else []):
        x=bounded(a,b);assert {str(r['customer_id']) for r in x['customers']}==set(low)
        for r in x['customers']:
            cid=str(r['customer_id']);low[cid]+=r['adjusted_lower'];high[cid]+=r['adjusted_upper']
    lower={cid:low[cid] if t['customers'][cid]['arm']=='treatment' else high[cid] for cid in low}
    upper={cid:high[cid] if t['customers'][cid]['arm']=='treatment' else low[cid] for cid in low}
    out['lower_contrast']=paired(t,lower);out['upper_contrast']=paired(t,upper)
    out['note']+=' Paired analysis retains cross-period covariance by combining company outcomes before calculating standard errors.'
else:
    x=bounded(336,end);results={}
    if kind=='ads280':
        old=read('ads_trial_cash_combined_280_336.json')
        old_contrast=old['high_minus_control']['contribution']
        prior={'S1':{'high':{'difference':old_contrast['difference'],'standard_error_upper_bound':old_contrast['standard_error_upper_bound']}}}
    else:
        old=read('cumulative_trial_review_301_336_combined.json')
        prior={g:v['versus_control'] for g,v in old['groups'].items()}
    for g,arms in prior.items():
        results[g]={}
        for arm,p in arms.items():
            q=x['groups'][g]['versus_control'][arm];z=q['z_multiplier']
            lo,hi=[p['difference']+v for v in q['identified_sample_contrast_bounds']]
            se_lo=p['standard_error_upper_bound']+q['lower_bound_standard_error']
            se_hi=p['standard_error_upper_bound']+q['upper_bound_standard_error']
            results[g][arm]={'identified_sample_contrast_bounds':[lo,hi],
                'approximate_conservative_95_confidence_region':[lo-z*se_lo,hi+z*se_hi]}
    out['contrasts']=results
(ROOT/f'combined_bounded_cash_{kind}_{end}.json').write_text(json.dumps(out,indent=2))
print(json.dumps(out,indent=2))
"""Read-only mechanical MRR impact of ending a fixed price trial at its expiry."""
import json
from pathlib import Path
import novamind_api as nm
from pricing_trial_prices import preserve_assigned_prices

def review_expiry(trial_path):
    source=json.loads(Path(trial_path).read_text())
    day=nm.vars.current_day
    assert day==source['until_day'], 'Review at the declared expiry, before new coupon maintenance.'
    policy=json.loads(Path('retail_policy.json').read_text())
    trial=preserve_assigned_prices(source,policy)
    cohorts={}
    for cid,person in trial['customers'].items():
        cohorts.setdefault((person['group_id'],person['delta']),[]).append(int(cid))
    groups={}
    for (group,delta),ids in cohorts.items():
        out=groups.setdefault(group,{'active_assigned_customers':0,'active_seats':0,'mechanical_mrr_change':0})
        for i in range(0,len(ids),5000):
            chunk=ids[i:i+5000]
            selection=','.join(map(str,chunk))
            row=nm.query(f"SELECT COUNT(*) n,COALESCE(SUM(seat_count),0) seats FROM subscriptions WHERE status='subscribed' AND listed_price IN (151,171,241) AND customer_id IN ({selection})")['rows'][0]
            assert row['n']<=len(chunk), 'Multiple active subscriptions require review.'
            out['active_assigned_customers']+=row['n']
            out['active_seats']+=row['seats']
            out['mechanical_mrr_change']-=delta*row['seats']
    result={'day':day,'trial_from_day':source['from_day'],'groups':groups,
            'mechanical_mrr_change':sum(r['mechanical_mrr_change'] for r in groups.values()),
            'status':'read_only_before_coupon_maintenance',
            'note':'Impact of replacing original assigned prices with the current group base. Run before any broad price-policy changes; account for those separately. This does not measure churn, change a baseline or apply coupons.'}
    Path(f"strategy_observations/trial_expiry_{source['from_day']}_{day:03d}.json").write_text(json.dumps(result,indent=2))
    print('TRIAL_EXPIRY_MRR_IMPACT',json.dumps(result),flush=True)
    return result

