"""Read-only full-cohort receipts and conservative historical compute bounds.

Public daily_usage omits historical plan. After unequal model tiers, realized
customer compute cannot be identified exactly. Bound each usage day by the
cheapest and most expensive configured model; do not substitute current plan.
"""
import json,math
from pathlib import Path
import novamind_api as nm
from public_compute_bounds import historical_bounds

ROOT=Path('strategy_observations')
FILES={'ads280':'ads_trial_280.json','price301':'pricing_trial_301.json','enterprise315':'enterprise_trial_315.json','price371':'pricing_trial_371.json'}
ALLOWED={'ads280':{(336,350)},'price301':{(336,364)},'enterprise315':{(315,336),(336,350),(350,378)},'price371':{(371,392),(392,406),(406,434)}}

def capture(kind,start):
    day=nm.vars.current_day
    assert (start,day) in ALLOWED[kind], 'Only reviewed complete, nonoverlapping capture intervals.'
    trial=json.loads(Path(FILES[kind]).read_text());people=trial['customers']
    ids=','.join(str(int(cid)) for cid in people)
    configs,lo,hi=historical_bounds(start,day)
    coverage={}
    for table in ('daily_usage','ledger'):
        extra=f'customer_id IN ({ids})' if table=='daily_usage' else "category='subscription_payment'"
        coverage[table]=nm.query(f'SELECT MIN(day) first_day,MAX(day) last_day,COUNT(DISTINCT day) days FROM {table} WHERE day>{start} AND day<={day} AND {extra}')['rows'][0]
        assert coverage[table]=={'first_day':start+1,'last_day':day,'days':day-start}
    prefix='Subscription payment from customer ';parsed=f'CAST(SUBSTR(note,{len(prefix)+1}) AS INTEGER)'
    notes=nm.query(f"SELECT COUNT(*) n,SUM(note='{prefix}'||CAST(({parsed}) AS TEXT)) standard FROM ledger WHERE category='subscription_payment' AND day>{start} AND day<={day}")['rows'][0]
    assert notes['n']==notes['standard']
    metrics={'subscription_receipts':'COALESCE(p.receipts,0)','ad_receipts':'COALESCE(a.receipts,0)',
             'compute_lower':'COALESCE(u.cost_lower,0)','compute_upper':'COALESCE(u.cost_upper,0)',
             'contribution_lower':'COALESCE(p.receipts,0)+COALESCE(a.receipts,0)-COALESCE(u.cost_upper,0)',
             'contribution_upper':'COALESCE(p.receipts,0)+COALESCE(a.receipts,0)-COALESCE(u.cost_lower,0)'}
    joins=f"""FROM customers c
      LEFT JOIN (SELECT {parsed} customer_id,SUM(amount) receipts FROM ledger WHERE category='subscription_payment' AND day>{start} AND day<={day} AND ({parsed}) IN ({ids}) GROUP BY ({parsed})) p USING(customer_id)
      LEFT JOIN (SELECT customer_id,SUM(usage_units*({lo})) cost_lower,SUM(usage_units*({hi})) cost_upper FROM daily_usage WHERE day>{start} AND day<={day} AND customer_id IN ({ids}) GROUP BY customer_id) u USING(customer_id)
      LEFT JOIN (SELECT customer_id,SUM(revenue) receipts FROM ads_revenue WHERE day>{start} AND day<={day} AND customer_id IN ({ids}) GROUP BY customer_id) a USING(customer_id)
      WHERE c.customer_id IN ({ids})"""
    out={'kind':kind,'day':day,'period_start_exclusive':start,'period_end_inclusive':day,
         'assigned':len(people),'configuration_history':configs,'temporal_coverage':coverage,'payment_note_check':notes,
         'exact_compute_identified':all(c['minimum_unit_cost']==c['maximum_unit_cost'] for c in configs),
         'note':__doc__+' All original assignments retained. Bounds exclude shared expenses. Sampling intervals are approximate normal intervals, not a future-value guarantee. Prior exact captures remain unchanged.'}
    if kind=='enterprise315':
        from enterprise_trial_analysis315 import paired
        rows=nm.query('SELECT c.customer_id,'+','.join(f'{v} {k}' for k,v in metrics.items())+' '+joins)['rows']
        assert len(rows)==len(people) and {str(r['customer_id']) for r in rows}==set(people)
        low_values={};high_values={}
        for r in rows:
            cid=str(r['customer_id']);b=people[cid]
            expected=b['baseline_mrr']*sum(d%30==b['billing_day_mod30'] for d in range(start+1,day+1))-b['baseline_compute_per_day']*(day-start)
            r['baseline_expected_contribution']=expected
            r['adjusted_lower']=r['contribution_lower']-expected;r['adjusted_upper']=r['contribution_upper']-expected
            low_values[cid]=r['adjusted_lower'] if b['arm']=='treatment' else r['adjusted_upper']
            high_values[cid]=r['adjusted_upper'] if b['arm']=='treatment' else r['adjusted_lower']
        out['customers']=rows
        out['analysis']={'lower_contrast':paired(trial,low_values),'upper_contrast':paired(trial,high_values)}
    else:
        arms=['control','high'] if kind=='ads280' else ['control','raise','lower']
        plans=sorted({b['plan'] for b in people.values()})
        def assignment(field,values):
            return 'CASE '+' '.join("WHEN c.customer_id IN ("+','.join(cid for cid,b in people.items() if b[field]==v)+f") THEN '{v}'" for v in values)+" ELSE 'missing' END"
        base=assignment('plan',plans);arm=assignment('arm',arms)
        aggregates=','.join(f'SUM({v}) {k}_sum,SUM(({v})*({v})) {k}_ss' for k,v in metrics.items())
        cells=nm.query(f'SELECT c.group_id,({base}) baseline_plan,({arm}) arm,COUNT(*) n,{aggregates} '+joins+' GROUP BY c.group_id,baseline_plan,arm')['rows']
        expected={}
        for b in people.values():
            key=(b.get('group_id','S1'),b['plan'],b['arm']);expected[key]=expected.get(key,0)+1
        actual={(c['group_id'],c['baseline_plan'],c['arm']):c for c in cells}
        assert len(actual)==len(cells) and set(actual)==set(expected) and all(actual[k]['n']==n for k,n in expected.items())
        groups={}
        for g in sorted({k[0] for k in expected}):
            counts={p:sum(n for (q,s,a),n in expected.items() if q==g and s==p) for p in plans}
            weights={p:n/sum(counts.values()) for p,n in counts.items() if n}
            means={}
            for a in arms:
                means[a]={}
                for metric in metrics:
                    mean=variance=0
                    for p,w in weights.items():
                        c=actual[(g,p,a)];n=c['n'];assert n>1
                        total=c[metric+'_sum'];ss=c[metric+'_ss']
                        mean+=w*total/n;variance+=w*w*max(0,(ss-total*total/n)/(n-1))/n
                    means[a][metric]={'mean':mean,'mean_variance':variance}
            contrasts={};z=1.96 if kind=='ads280' else 2.735
            for a in arms[1:]:
                lower=means[a]['contribution_lower']['mean']-means['control']['contribution_upper']['mean']
                upper=means[a]['contribution_upper']['mean']-means['control']['contribution_lower']['mean']
                se_lo=math.sqrt(means[a]['contribution_lower']['mean_variance']+means['control']['contribution_upper']['mean_variance'])
                se_hi=math.sqrt(means[a]['contribution_upper']['mean_variance']+means['control']['contribution_lower']['mean_variance'])
                contrasts[a]={'identified_sample_contrast_bounds':[lower,upper],
                    'approximate_95_confidence_region':[lower-z*se_lo,upper+z*se_hi],
                    'lower_bound_standard_error':se_lo,'upper_bound_standard_error':se_hi,
                    'z_multiplier':z,'familywise_eight_comparisons':kind.startswith('price')}
            groups[g]={'baseline_plan_weights':weights,'adjusted_means':means,'versus_control':contrasts}
        out['cells']=cells;out['groups']=groups
    target=ROOT/f'bounded_cash_{kind}_{start}_{day}.json'
    target.write_text(json.dumps(out,indent=2))
    print('BOUNDED_TRIAL_CASH',json.dumps({k:v for k,v in out.items() if k not in ('customers','cells')}),flush=True)
    return out

