import novamind_api as nm,json
from pathlib import Path
D=nm.vars.current_day
out={}
prior_paths=sorted(p for p in Path('strategy_observations').glob('insights_*.json') if int(p.stem.rsplit('_',1)[1])<D)
prior=json.loads(prior_paths[-1].read_text()) if prior_paths else {}
for g in nm.market.get_market_overview()['known_groups']:
    r=nm.market.get_group_insights(g['group_id'])
    out[g['group_id']]=r
    if prior.get(g['group_id'])!=r:
        print('CHANGED_STUDY',g['group_id'],'level',r['info_level'],json.dumps(r['estimates']),flush=True)
Path(f'strategy_observations/insights_{D:03d}.json').write_text(json.dumps(out,indent=2))
print('ALL_GROUP_INSIGHTS_SAVED',D,len(out),flush=True)

