"""Read-only public outcomes for the fixed day280 S1 advertising experiment."""
import json,math
from pathlib import Path
import novamind_api as nm

ROOT=Path('strategy_observations')

def context():
    trial=json.loads(Path('ads_trial_280.json').read_text())
    assert json.loads((ROOT/'ads_trial_start_280.json').read_text())['status']=='complete'
    people=trial['customers'];day=nm.vars.current_day
    extension=Path('ads_trial_extension_315.json')
    last_review=json.loads(extension.read_text())['review_day'] if extension.exists() else 315
    assert trial['from_day']==280 and 287<=day<=last_review
    ids=','.join(str(int(cid)) for cid in people)
    a_ids=','.join(str(int(cid)) for cid,r in people.items() if r['plan']=='A')
    high_ids=','.join(str(int(cid)) for cid,r in people.items() if r['arm']=='high')
    plan=f"CASE WHEN c.customer_id IN ({a_ids}) THEN 'A' ELSE 'B' END"
    arm=f"CASE WHEN c.customer_id IN ({high_ids}) THEN 'high' ELSE 'control' END"
    return trial,people,day,ids,plan,arm

def tier_guard(start,day):
    q=f'SELECT COUNT(*) n,MIN(day) first_setting_day,MIN(tier_A) lo_a,MAX(tier_A) hi_a,MIN(tier_B) lo_b,MAX(tier_B) hi_b,MIN(tier_C) lo_c,MAX(tier_C) hi_c FROM config_history WHERE day>=(SELECT MAX(day) FROM config_history WHERE day<={start}) AND day<={day}'
    config=nm.query(q)['rows'][0]
    assert config['n'] and config['first_setting_day']<=start
    assert all(config[k]==3 for k in ['lo_a','hi_a','lo_b','hi_b','lo_c','hi_c']), 'Historical compute costs changed; adapt observation before claiming complete contribution.'
    return config

def summarize(cells,people,metrics):
    expected={}
    for r in people.values():
        key=(r['plan'],r['arm']);expected[key]=expected.get(key,0)+1
    actual={(r['baseline_plan'],r['arm']):r for r in cells}
    assert set(actual)==set(expected) and len(actual)==len(cells)
    assert all(actual[k]['n']==n for k,n in expected.items()), 'Fixed assignment counts changed or subscription rows duplicated.'
    weights={p:sum(n for (q,a),n in expected.items() if q==p)/len(people) for p in 'AB'}
    arms={}
    for arm in ['control','high']:
        arms[arm]={}
        for metric in metrics:
            mean=variance=0
            for p,w in weights.items():
                r=actual[(p,arm)];n=r['n'];s=r[metric+'_sum'];ss=r[metric+'_ss']
                mean+=w*s/n
                variance+=w*w*max(0,(ss-s*s/n)/(n-1))/n
            arms[arm][metric]={'mean':mean,'mean_variance':variance}
    contrasts={}
    for metric in metrics:
        delta=arms['high'][metric]['mean']-arms['control'][metric]['mean']
        se=math.sqrt(arms['high'][metric]['mean_variance']+arms['control'][metric]['mean_variance'])
        contrasts[metric]={'difference':delta,'standard_error':se,'ci95':[delta-1.96*se,delta+1.96*se]}
    return {'baseline_plan_weights':weights,'adjusted_means':arms,'high_minus_control':contrasts}

def aggregates(metrics):
    return ','.join(f'SUM({x}) {m}_sum,SUM(({x})*({x})) {m}_ss' for m,x in metrics.items())

def exposure(day,ids,plan,arm):
    return nm.query(f"SELECT ({arm}) arm,MIN(a.ads_strength) minimum_strength,MAX(a.ads_strength) maximum_strength,SUM(a.revenue) receipts,COUNT(DISTINCT a.customer_id) customers FROM ads_revenue a JOIN customers c USING(customer_id) WHERE a.day>{day-7} AND a.day<={day} AND c.customer_id IN ({ids}) GROUP BY arm")['rows']

def endpoint():
    trial,people,day,ids,plan,arm=context()
    from public_compute_bounds import current_costs,cost_case
    config,costs=current_costs()
    active="s.status='subscribed'"
    revenue=f'CASE WHEN {active} THEN s.effective_price*s.seat_count ELSE 0 END'
    ad=f'CASE WHEN {active} THEN COALESCE(a.daily_ads,0)*30 ELSE 0 END'
    compute=f'CASE WHEN {active} THEN COALESCE(u.daily_units,0)*({cost_case(costs)})*30 ELSE 0 END'
    metrics={'survival':f'CASE WHEN {active} THEN 1 ELSE 0 END','subscription_revenue':revenue,'ad_revenue':ad,'compute':compute,'contribution':f'({revenue})+({ad})-({compute})'}
    sql=f"""SELECT ({plan}) baseline_plan,({arm}) arm,COUNT(*) n,{aggregates(metrics)}
    FROM customers c JOIN subscriptions s USING(customer_id)
    LEFT JOIN (SELECT customer_id,AVG(usage_units) daily_units FROM daily_usage WHERE day>{day-7} AND day<={day} AND customer_id IN ({ids}) GROUP BY customer_id) u USING(customer_id)
    LEFT JOIN (SELECT customer_id,SUM(revenue)/7.0 daily_ads FROM ads_revenue WHERE day>{day-7} AND day<={day} AND customer_id IN ({ids}) GROUP BY customer_id) a USING(customer_id)
    WHERE c.customer_id IN ({ids}) GROUP BY baseline_plan,arm"""
    cells=nm.query(sql)['rows']
    output={'day':day,'first_renewals_mature':day>=310,'planned_mature_review':315,'assigned':len(people),'configuration_check':config,'exposure':exposure(day,ids,plan,arm),'cells':cells,'analysis':summarize(cells,people,metrics),
        'note':'Fixed-assignment intention-to-treat endpoint per original assignee, standardized to pooled baseline A/B mix. Cancelled customers contribute zero. Monthly projection uses current plan/model cost with recent usage, current subscription price and recent ad receipts. Historical plan changes can mix usage; this is not realized compute or cumulative cash. Group reputation spillover can affect controls. No game action.'}
    (ROOT/f'ads_trial_endpoint_280_{day:03d}.json').write_text(json.dumps(output,indent=2))
    print('ADS_ENDPOINT',json.dumps({k:v for k,v in output.items() if k!='cells'}),flush=True)

def cash(start):
    trial,people,day,ids,plan,arm=context()
    allowed=[(280,301),(301,315)]
    extension=Path('ads_trial_extension_315.json')
    if extension.exists():allowed += [tuple(x) for x in json.loads(extension.read_text())['cash_periods']]
    assert (start,day) in allowed, 'Capture only planned nonoverlapping periods.'
    if start>=336:
        from bounded_trial_cash import capture
        return capture('ads280',start)
    config=tier_guard(start,day);coverage={}
    for table in ['daily_usage','ads_revenue','ledger']:
        extra="category='subscription_payment'" if table=='ledger' else f'customer_id IN ({ids})'
        coverage[table]=nm.query(f'SELECT MIN(day) first_day,MAX(day) last_day,COUNT(DISTINCT day) days FROM {table} WHERE day>{start} AND day<={day} AND {extra}')['rows'][0]
        print('ADS_CASH_COVERAGE',table,json.dumps(coverage[table]),flush=True)
        assert coverage[table]=={'first_day':start+1,'last_day':day,'days':day-start}, 'Incomplete public history; do not claim full period.'
    prefix='Subscription payment from customer '
    parsed=f'CAST(SUBSTR(note,{len(prefix)+1}) AS INTEGER)'
    exact=f"note='{prefix}'||CAST(({parsed}) AS TEXT)"
    notes=nm.query(f"SELECT COUNT(*) n,SUM(CASE WHEN {exact} THEN 1 ELSE 0 END) standard FROM ledger WHERE category='subscription_payment' AND day>{start} AND day<={day}")['rows'][0]
    assert notes['n']==notes['standard'], 'Unmapped payment note.'
    metrics={'subscription_receipts':'COALESCE(p.receipts,0)','ad_receipts':'COALESCE(a.receipts,0)','compute':'COALESCE(u.units,0)*0.006','contribution':'COALESCE(p.receipts,0)+COALESCE(a.receipts,0)-COALESCE(u.units,0)*0.006'}
    sql=f"""SELECT ({plan}) baseline_plan,({arm}) arm,COUNT(*) n,{aggregates(metrics)} FROM customers c
    LEFT JOIN (SELECT {parsed} customer_id,SUM(amount) receipts FROM ledger WHERE category='subscription_payment' AND day>{start} AND day<={day} AND ({parsed}) IN ({ids}) GROUP BY ({parsed})) p USING(customer_id)
    LEFT JOIN (SELECT customer_id,SUM(usage_units) units FROM daily_usage WHERE day>{start} AND day<={day} AND customer_id IN ({ids}) GROUP BY customer_id) u USING(customer_id)
    LEFT JOIN (SELECT customer_id,SUM(revenue) receipts FROM ads_revenue WHERE day>{start} AND day<={day} AND customer_id IN ({ids}) GROUP BY customer_id) a USING(customer_id)
    WHERE c.customer_id IN ({ids}) GROUP BY baseline_plan,arm"""
    cells=nm.query(sql)['rows']
    output={'day':day,'period_start_exclusive':start,'period_end_inclusive':day,'assigned':len(people),'configuration_check':config,'temporal_coverage':coverage,'payment_note_check':notes,'cells':cells,'analysis':summarize(cells,people,metrics),
        'note':'Realized fixed-cohort subscription and in-app ad receipts minus observed usage at verifiedconstant tier3 compute cost. All original assignees included. Excludes shared expenses and unassigned acquisition. Interval only; combine saved nonoverlapping301 and315 captures before claiming full35day contribution. No game action.'}
    (ROOT/f'ads_trial_cash_280_{start}_{day}.json').write_text(json.dumps(output,indent=2))
    print('ADS_CASH',json.dumps({k:v for k,v in output.items() if k!='cells'}),flush=True)

