"""Pure price-basis arithmetic; no simulator calls or file writes."""

LIST_PRICES={'A':151,'B':171,'C':241}

def preserve_assigned_prices(trial,policy):
    """Express immutable experimental prices relative to the current base price."""
    assert policy['prices']==LIST_PRICES, 'Review active trials before changing list prices.'
    people={}
    for cid,person in trial['customers'].items():
        assert person['listed_price']==LIST_PRICES[person['plan']]
        original_offset=LIST_PRICES[person['plan']]-LIST_PRICES['A']
        original_base=person['baseline_recurring_price']-original_offset
        relative_delta=original_base+person['delta']-policy['target_A'][person['group_id']]
        people[cid]=dict(person,delta=relative_delta)
    return dict(trial,customers=people)

"""Pure calculations shared by strategy actions and forecasts."""

def shared_development_for_day(day,policy):
    amount=40000 if day<420 else 20000
    for period in (policy or {}).get('shared_temporary',[]):
        if period['from_day']<=day<period['until_day']:
            amount=period['daily_spend']
    return amount

def adjusted_mrr_changes(states):
    """Newest first; remove the one-time price effect from each affected change."""
    return [states[i]['mrr']-states[i+1]['mrr']-states[i].get('one_time_mrr_change',0)
            for i in range(len(states)-1)]

