for z in json.loads((r/'day406.json').read_text())['issues']:
 if z['group_id'] in ops:ops[z['group_id']]=max(ops[z['group_id']],z['n']*25)
print('targeted ops',sum(ops.values()),ops)
print('dailycompute',json.loads((r/'contribution_window_406.json').read_text())['totals']['projected_monthly_compute']/30)
PY"

