    "type": "add",
    "content": """"Read-only first renewal check for the fixed ongoing434 price rollout."""
import json
from pathlib import Path
import novamind_api as nm
assert nm.vars.current_day==441
p=json.loads(Path('retail_price_rollout_434.json').read_text())
ids=list(p['customers']);billdays=','.join(str((434+i)%30) for i in range(1,8))
total={'renewed_active':0,'mismatches':0}
for i in range(0,len(ids),2000):
 r=nm.query(f"SELECT COUNT(*) renewed_active,COALESCE(SUM(ABS(effective_price-(listed_price-151+36))>.00001),0) mismatches FROM subscriptions WHERE status='subscribed' AND listed_price IN (151,171,241) AND billing_day_mod30 IN ({billdays}) AND customer_id IN ({','.join(ids[i:i+2000])})")['rows'][0]
 for k in total:total[k]+=r[k]
with Path('strategy_observations/price_rollout_application_audit_441.json').open('x') as f:json.dump({'day':441,**total},f,indent=2)
print('PRICE_ROLLOUT_APPLICATION_AUDIT',json.dumps(total),flush=True)
assert total['mismatches']==0
