"""Narrow price-floor exception for explicit, same-plan retention counters."""
import math

def quote_for_counter(status,thread_type,current_plan,requested_plan,requested_price,monthly_compute):
    if status!='subscribed' or thread_type not in ('churn_prevention','renewal'):
        return None
    if requested_plan not in ('A','B','C'):
        return None
    if requested_plan!=current_plan or not isinstance(requested_price,(int,float)):
        return None
    if not math.isfinite(requested_price) or not math.isfinite(monthly_compute) or monthly_compute<0:
        return None
    quote=math.floor(requested_price*100+1e-9)/100
    minimum=math.ceil(max(3,monthly_compute*1.10,monthly_compute+2)*100)/100
    old_floor=max(3,monthly_compute*1.35)
    if minimum<=quote<old_floor:
        return [requested_plan,quote]
    return None

